func:
// Speichert jeden Messwert mit Zeitstempel, damit "Messung erstellen" veraltete Werte erkennt.
// msg.topic ist der Node-Name, z. B. "grid L1" oder "vebus F".
const values = flow.get("ortsnetz") || {};
values[msg.topic] = { v: typeof msg.payload === "number" ? msg.payload : null, t: Date.now() };
flow.set("ortsnetz", values);
node.status({fill: "green", shape: "dot", text: "L1: " + values["vebus L1"].v + ", L2: " + values["vebus L2"].v + ", L3: " + values["vebus L3"].v});
return null;

// ---------------- Konfiguration ----------------
const LATITUDE = 52.520008;
const LONGITUDE = 13.404954;
// Optional: tatsächliche installierte PV-Leistung in kWp, sonst null (wird dann nicht übertragen)
const PLANT_KWP = null;
const PV_FORECAST_KWH = null;   // optional, z. B. 24.5
const SMARTMETER_MODEL = "Victron GX NodeRed";
const API_URL = "https://www.ortsnetz-auslastung.de/v1/measurements";
// Werte, die länger nicht aktualisiert wurden, gelten als ungültig (Gerät getrennt)
const MAX_AGE_MS = 60 * 1000;
// -----------------------------------------------
const VERSION = "venus-nodered-0.1.0";

const values = flow.get("ortsnetz") || {};

function get(key) {
    const e = values[key];
    if (!e || e.v === null || Date.now() - e.t > MAX_AGE_MS) return null;
    return e.v;
}

const round = (v, digits) => Math.round(v * 10 ** digits) / 10 ** digits;
const validV = (v) => (v !== null && v >= 150 && v <= 300 ? round(v, 1) : -1);
const validForecast = (v) => (typeof v === "number" && v >= 0 && v <= 100000 ? round(v, 2) : null);

// Reihenfolge wie im Python-Script: 1. Netzzähler, 2. VE.Bus
let source = null;
let volts = [null, null, null];
let freq = null;
for (const prefix of ["grid", "vebus"]) {
    const v = [1, 2, 3].map((i) => get(`${prefix} L${i}`));
    if (validV(v[0]) !== -1) {
        source = prefix;
        volts = v;
        freq = get(`${prefix} F`);
        break;
    }
}

const [l1, l2, l3] = volts.map(validV);
if (l1 === -1) {
    node.status({ fill: "red", shape: "ring", text: "keine gültige L1-Spannung" });
    node.warn("Keine gültige L1-Spannung (Quelle: keine gefunden) – übersprungen");
    return null;
}

const payload = {
    observed_at: new Date().toISOString().replace(/\.\d{3}Z$/, "Z"),
    latitude: LATITUDE,
    longitude: LONGITUDE,
    l1_v: l1,
    l2_v: l2,
    l3_v: l3,
    smartmeter_model: SMARTMETER_MODEL,
    integration_version: VERSION,
};
if (freq !== null && freq >= 45 && freq <= 55) payload.grid_frequency_hz = round(freq, 2);
if (PLANT_KWP) payload.plant_capacity_kwp = PLANT_KWP;
const forecast = validForecast(PV_FORECAST_KWH);
if (forecast !== null) payload.pv_forecast_kwh = forecast;

node.status({ fill: "blue", shape: "dot", text: `${source}: L1=${l1} L2=${l2} L3=${l3} V` });
return {
    url: API_URL,
    method: "POST",
    headers: { "Content-Type": "application/json" },
    payload: payload,
    source: source,
    requestTimeout: 15000,
};

// Messung für die Auswertung merken, http request ersetzt msg.payload durch die Antwort
msg.req_payload = msg.payload;
return msg;

const p = msg.req_payload || {};
if (msg.statusCode >= 200 && msg.statusCode < 300) {
    const body = typeof msg.payload === "object" && msg.payload !== null ? msg.payload : {};
    const overall = (body.status && body.status.overall) || "?";
    const text = `OK (${msg.source}): L1=${p.l1_v} L2=${p.l2_v} L3=${p.l3_v} V, f=${p.grid_frequency_hz ?? "-"} Hz -> ${overall}`;
    node.status({ fill: overall == "green" ? "green" : "blue", shape: "dot", text: text });
    node.log(text);
} else if (typeof msg.statusCode === "number") {
    const body = typeof msg.payload === "string" ? msg.payload : JSON.stringify(msg.payload);
    node.status({ fill: "red", shape: "dot", text: `HTTP ${msg.statusCode}` });
    node.warn(`HTTP ${msg.statusCode}: ${body}`);
} else {
    node.status({ fill: "red", shape: "dot", text: "Übertragung fehlgeschlagen" });
    node.warn(`Übertragung fehlgeschlagen: ${msg.payload}`);
}
return null;
